import {lobbyPetMarkup} from './lobby-pets.js';
import {petsServiceView} from './pets-service.js';
import {caretakerAssets} from './caretaker-assets.js';
import {petDetails} from './pets-details.js';
import {PET_PAGE_SIZE} from './pets-selection.js';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rarityLabel=tier=>({comum:'COMUM',incomum:'INCOMUM',raro:'RARO',epico:'ÉPICO',lendario:'LENDÁRIO'}[tier]||'');
const rarityIcon=tier=>{
 const colors={comum:'#ffffff',incomum:'#79e624',raro:'#29c8ff',epico:'#d073ff',lendario:'#ffbc00'};
 const shape=tier==='all'?'<g fill="currentColor"><rect x="2" y="2" width="7" height="7" rx="1.3"/><rect x="11" y="2" width="7" height="7" rx="1.3"/><rect x="2" y="11" width="7" height="7" rx="1.3"/><rect x="11" y="11" width="7" height="7" rx="1.3"/></g>':colors[tier]?'<circle cx="10" cy="10" r="7.5" fill="'+colors[tier]+'" stroke="#031b37" stroke-width="1.5"/>':'';
 return shape?'<svg class="gv-pets__rarity-icon" data-rarity-symbol="'+tier+'" viewBox="0 0 20 20" aria-hidden="true" focusable="false">'+shape+'</svg>':'';
};
const visuals={'slime-friend':{type:'slime',biome:0},'bat-friend':{type:'bat',biome:0}};
const lockReason=p=>p.unlockHint||'JORNADA INDISPONÍVEL';
const journey=p=>p.preview?'<p class="gv-pets__journey-note">Desbloqueio planejado: '+escape(p.unlock)+'</p>':!p.owned&&p.journey?.steps?.length?'<ul class="gv-pets__journey" aria-label="Objetivos de vínculo">'+p.journey.steps.map(step=>'<li><span aria-label="'+(step.done?'Concluído':'Pendente')+'">'+(step.done?'✓':'○')+'</span>'+escape(step.label)+'</li>').join('')+'</ul>':'';
const art=p=>'<div class="gv-pets__detail-stage"><img class="gv-pets__pedestal" src="'+caretakerAssets.pedestal+'" alt=""><div class="relic-art" aria-hidden="true">'+lobbyPetMarkup(p.id)+'</div></div>';
const portrait='<svg class="gv-pets__portrait" viewBox="290 40 750 700" aria-hidden="true"><image href="'+caretakerAssets.portrait+'" width="1351" height="1164"/></svg>';
const stage=p=>'<div class="gv-pets__card-stage"><img class="gv-pets__pedestal" src="'+caretakerAssets.pedestal+'" alt=""><div class="relic-art pet-card-portrait" aria-hidden="true">'+lobbyPetMarkup(p.id)+'</div></div>';
const states=p=>[!p.owned?'<span class="gv-pets__state">'+(p.preview?'EM PREPARAÇÃO':'BLOQUEADO')+'</span>':'',p.equipped?'<span class="gv-pets__state gv-pets__state--equipped">✓ EQUIPADO</span>':'',p.cared?'<span class="gv-pets__state gv-pets__state--cared">CARINHO EM DIA</span>':''].join('');
const equipButton=(p,where)=>'<button type="button" class="primary gv-pets__equip" data-pet-equip="'+escape(p.id)+'" data-pet-action-key="'+where+'-equip-'+escape(p.id)+'" aria-label="'+escape((p.equipped?'DESEQUIPAR — ':'EQUIPAR — ')+p.name)+'" aria-describedby="gv-pet-'+escape(p.id)+'-state gv-pet-'+escape(p.id)+'-detail" aria-pressed="'+String(p.equipped)+'" '+(!p.equip.available?'disabled':'')+'>'+(where==='detail'&&!p.preview?'✓ ':'')+(p.preview?'EM PREPARAÇÃO':p.equipped?'EQUIPADO':'EQUIPAR')+'</button>';
export function petsMarkup(profile){
 const view=petsServiceView(profile),status='<p id="petsStatus" role="status" aria-live="polite"></p>';
 if(!view.supported)return '<section class="gv-pets gv-pets--caregiver"><h2 id="petsTitle" tabindex="-1">COMPANHEIROS</h2><p role="status">Coleção indisponível. Seus dados foram preservados.</p>'+status+'</section>';
 const selected=view.activePet||view.pets.find(p=>p.owned)?.id||view.pets[0]?.id;
 const initialPage=Math.floor(view.pets.findIndex(p=>p.id===selected)/PET_PAGE_SIZE);
 const cards=view.pets.map((p,index)=>{
  const id=escape(p.id),name=escape(p.name),meta=petDetails[p.id]||{};
  return '<article class="gv-pets__card '+(p.owned?'owned':'is-locked')+'" data-pet-card="'+id+'" data-pet-tier="'+escape(meta.rarity||'unknown')+'" data-selected="'+String(p.id===selected)+'" '+(Math.floor(index/PET_PAGE_SIZE)!==initialPage?'hidden':'')+'><button type="button" class="gv-pets__select" data-pet-select="'+id+'" aria-label="Ver '+name+'" aria-pressed="'+String(p.id===selected)+'" aria-controls="gv-pet-'+id+'-panel">'+stage(p)+'<span class="gv-pets__card-tier">'+rarityIcon(meta.rarity)+rarityLabel(meta.rarity)+'</span><span class="gv-pets__card-name">'+name+'</span><span class="gv-pets__card-copy">'+escape(p.owned?p.effect:lockReason(p))+'</span><span class="gv-pets__states">'+states(p)+'</span></button>'+equipButton(p,'card')+'</article>';
 }).join('');
 const details=view.pets.map(p=>{
  const id=escape(p.id),name=escape(p.name),meta=petDetails[p.id]||{},stateId='gv-pet-'+id+'-state',detailId='gv-pet-'+id+'-detail',nameId='gv-pet-'+id+'-name';
  const classes=['gv-pets__detail',p.owned?'owned':'is-locked',p.equipped?'is-equipped':'',p.cared?'is-cared':''].filter(Boolean).join(' ');
  return '<article class="'+classes+'" data-pet-id="'+id+'" data-pet-panel="'+id+'" id="gv-pet-'+id+'-panel" aria-labelledby="'+nameId+'" '+(p.id!==selected?'hidden':'')+'><div class="gv-pets__scene" data-scene-state="approved">'+(meta.rarity?'<span class="gv-pets__rarity">'+rarityIcon(meta.rarity)+rarityLabel(meta.rarity)+'</span>':'')+'<h3 id="'+nameId+'">'+name+'</h3>'+art(p)+'</div><div class="gv-pets__information"><p class="gv-pets__eyebrow">✦ HABILIDADE</p><h4 class="gv-pets__ability">'+escape(meta.abilityName||'NOME DA HABILIDADE A DEFINIR')+'</h4><strong id="'+detailId+'">'+escape(p.effect)+'</strong>'+(!p.owned?(p.journey?.steps?.length?journey(p):'<p class="gv-pets__requirement">'+escape(lockReason(p))+'</p>'):'')+'<p class="gv-pets__states" id="'+stateId+'">'+states(p)+'</p></div><div class="gv-pets__actions"><button type="button" class="secondary" data-pet-care="'+id+'" data-pet-action-key="detail-care-'+id+'" aria-label="'+escape('CUIDAR — '+p.name)+'" aria-describedby="'+stateId+' '+detailId+'" '+(!p.care.available?'disabled':'')+'>♥ CUIDAR</button>'+equipButton(p,'detail')+'</div></article>';
 }).join('');
 const filters=[['all','TODOS'],['comum','COMUM'],['incomum','INCOMUM'],['raro','RARO'],['epico','ÉPICO'],['lendario','LENDÁRIO']].filter(([key])=>key==='all'||view.pets.some(p=>petDetails[p.id]?.rarity===key)).map(([key,label])=>'<button type="button" data-pet-filter="'+key+'" aria-pressed="'+String(key==='all')+'">'+rarityIcon(key)+label+'</button>').join('');
 return '<section class="gv-pets gv-pets--caregiver" data-pet-initial="'+escape(selected)+'"><p class="gv-pets__intro">Escolha um companheiro da sua coleção e prepare sua próxima expedição.</p><div class="gv-pets__layout"><div class="gv-pets__gallery"><h2 id="petsTitle" tabindex="-1">COMPANHEIROS</h2><nav class="gv-pets__filters" aria-label="Filtrar por raridade">'+filters+'</nav><div class="gv-pets__cards">'+cards+'</div><nav class="gv-pets__pagination" aria-label="Páginas de companheiros"><button type="button" data-pet-page="previous" aria-label="Página anterior de pets" '+(initialPage===0?'disabled':'')+'>‹</button><span data-pet-page-label role="status" aria-live="polite">'+(initialPage+1)+' / '+Math.ceil(view.pets.length/PET_PAGE_SIZE)+'</span><button type="button" data-pet-page="next" aria-label="Próxima página de pets" '+(initialPage>=Math.ceil(view.pets.length/PET_PAGE_SIZE)-1?'disabled':'')+'>›</button></nav><p id="petsFilterEmpty" role="status" hidden>Nenhum companheiro nesta raridade. Veja TODOS ou COMUM.</p>'+status+'</div><aside class="gv-pets__sidebar" aria-label="Detalhes do companheiro">'+details+'<p id="petsDetailEmpty" hidden>Selecione TODOS ou COMUM para ver os companheiros disponíveis.</p></aside></div></section>';
}
